import { LANG } from './i18n'

// The words for scanner/deep.py. The server sends a code and parameters; {name} is filled in here.
// [title, what was found, how to fix]. tests/test_deep.py checks every code the server can send is here.
export type Entry = [string, string, string?]
export type ChainWords = { title: string; fact: string; could: string; fix: string }
type Words = {
  items: Record<string, Entry>
  chains: Record<string, ChainWords>
  ui: {
    tab: string; about: string; start: string; running: string; passive: string
    modules: Record<'surface' | 'mail' | 'tech' | 'tls' | 'reputation' | 'active', string>
    retry: string; failed: string; chainsTitle: string; chainsLead: string; chainsNone: string; chainsWait: string
    levels: Record<'critical' | 'high' | 'medium', string>
    fact: string; could: string; fix: string
    hosts: string; software: string; none: string; nameservers: string; records: string; lists: string
    flags: Record<'takeover' | 'dangling' | 'sensitive' | 'private', string>; offline: string
    safeBrowsing: string; since: (date: string) => string; newHosts: string; newProblems: string; solved: string; noChange: string
    ownTitle: string; ownLead: string; ownOnly: string; ownStart: string; ownDns: string; ownDnsHint: string; ownFile: string; ownFileHint: string; ownCode: string
    ownCheck: string; ownChecking: string; ownNotYet: string; limits: string
  }
}

