export const ALL_WORDS = { AZ, EN, RU }
export const d: Words = LANG === 'ru' ? RU : LANG === 'en' ? EN : AZ

export function fill(text: string, params: Record<string, unknown>): string {
  return text.replace(/\{(\w+)\}/g, (whole, name) => (params[name] === undefined ? whole : String(params[name])))
}
